// Helper: force anything into a finite Number (or fallback)
const asNumber = (v, fallback = 0) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
};

// Helper: clamp number
const clamp = (n, min, max) => Math.min(max, Math.max(min, n));

// Helper: publish without msg object reuse issues
const pub = (topic, payload) => node.send({ topic, payload });

// ---- Read inputs (force to numbers) ----
const dr = msg.payload?.DataRecord ?? [];

const TotalHeatEnergy = asNumber(dr[0]?.Value, 0);
const FlowTemperature = asNumber(dr[6]?.Value, 0) / 100;
const ReturnTemperature = asNumber(dr[7]?.Value, 0) / 100;
const DiffTemperature = asNumber(dr[8]?.Value, 0) / 100;
const Power = asNumber(dr[9]?.Value, 0) / 10;
const FlowValue = asNumber(dr[11]?.Value, 0) / 1000;

// ---- Read statuses ----
const compressor_status = !!global.get("compressor_status");
const defrost_status = !!global.get("defrost_status");
const dhw_status = !!global.get("dhw_status");

// ---- Read state (force to numbers) ----
let prev_kwh = asNumber(flow.get("prev_kwh"), NaN);
let room_kwh = asNumber(flow.get("room_kwh"), 0);
let dwh_kwh = asNumber(flow.get("dwh_kwh"), 0);

// Initialize prev_kwh on first run / invalid
if (!Number.isFinite(prev_kwh) || prev_kwh <= 0) {
    prev_kwh = TotalHeatEnergy;
}

// Delta since last sample (protect against negative resets/rollover)
let delta_kwh = TotalHeatEnergy - prev_kwh;
if (!Number.isFinite(delta_kwh) || delta_kwh < 0) delta_kwh = 0;

// ---- Pe / COPH ----
let Pe = asNumber(flow.get("pe"), 0);

// Raw COPH sample for this message
let coph_sample = 0.0;

if (compressor_status && Pe > 0) {
    const COPH = Power / Pe;
    coph_sample = asNumber(COPH, 0);
    coph_sample = clamp(coph_sample, -5.0, 5.0);
} else {
    coph_sample = 0.0;
}

// ---- 60 second rolling average ----
const now = Date.now();
const windowMs = 60 * 1000;

// Stored as: [{t: 1234567890, v: 3.21}, ...]
let coph_samples = flow.get("coph_samples");
if (!Array.isArray(coph_samples)) coph_samples = [];

// Add current sample
coph_samples.push({ t: now, v: coph_sample });

// Keep only last 60 seconds
coph_samples = coph_samples.filter(s => (now - s.t) <= windowMs);

// Average
let coph_int = 0.0;
if (coph_samples.length > 0) {
    const sum = coph_samples.reduce((acc, s) => acc + asNumber(s.v, 0), 0);
    coph_int = sum / coph_samples.length;
}

// Round final published value
coph_int = asNumber(coph_int.toFixed(2), 0);

// ---- Allocate energy to DHW or room (skip room during defrost) ----
if (dhw_status) {
    dwh_kwh += delta_kwh;
    pub("hp_production/dhw_heatenergy", dwh_kwh);
} else if (!defrost_status) {
    room_kwh += delta_kwh;
    pub("hp_production/room_heatenergy", room_kwh);
}

// ---- Publish signals ----
pub("hp_production/totalheatenergy", TotalHeatEnergy);
pub("hp_production/flowtemperature", FlowTemperature);
pub("hp_production/returntemperature", ReturnTemperature);
